use strict;
use warnings;
use Test::More;
use Accounts;

sub corsair_marker {
    open(my $fh, '>', "$ENV{CORSAIR_MARKER_DIR}/$_[0]") or die "marker $_[0]: $!";
    print $fh $_[1] if defined $_[1];
    close($fh);
}

{
    package RecordingDb;
    sub new { my ($class) = @_; return bless { calls => [] }, $class }
    sub selectall_arrayref {
        my ($self, $sql, $attributes, @bind) = @_;
        push @{ $self->{calls} }, [$sql, @bind];
        return [[25]];
    }
}

corsair_marker('start');
my $dbh = RecordingDb->new;
my $rows = Accounts::balance($dbh, 'alice');
my $holds = ref($rows) eq 'ARRAY' && $rows->[0][0] == 25 && @{ $dbh->{calls} } == 1;
corsair_marker('check', $holds ? 'holds' : 'violated');
ok($holds, 'benign_control') or diag($ENV{CORSAIR_TOKEN});
corsair_marker('end') if Test::More->builder->is_passing;
done_testing();

